unsigned char CSaveGameEdit::IgnoreKey(message* msg)
{
    switch (msg->codeX) {
    case KEYCODE_KP_DECIMAL:
        if (HIWORD(GetKeyState(VK_CONTROL)))
            return 1;
        break;
    case KEYCODE_PERIOD:
        if (HIWORD(GetKeyState(VK_SHIFT)))
            goto ignore;
        return 1;
    case KEYCODE_2:
    case KEYCODE_5:
    case KEYCODE_8:
    case KEYCODE_SEMICOLON:
    case KEYCODE_APOSTROPHE:
    case KEYCODE_GRAVE:
    case KEYCODE_COMMA:
        if (HIWORD(GetKeyState(VK_SHIFT)))
            return 1;
        break;
    case KEYCODE_ESCAPE:
    case KEYCODE_TAB:
    case KEYCODE_ENTER:
    case KEYCODE_BACKSLASH:
    case KEYCODE_SLASH:
    case KEYCODE_KP_8:
    case KEYCODE_KP_9:
    case KEYCODE_KP_2:
    case KEYCODE_KP_3:
    ignore:
        return 1;
    }
    return 0;
}

